    tarea = [
        (t("The columns of power (20 minutes).", "Las columnas del poder (20 minutos)."), t("Copy the table of section 1 with the right column covered. Write the limit of each power from memory. <em>Check:</em> every limit names another branch or level of government.", "Copie la tabla de la sección 1 tapando la columna derecha. Escriba de memoria el límite de cada facultad. <em>Compruebe:</em> cada límite nombra otro poder u otro nivel de gobierno.")),
        (t("Three measures in the news (30 minutes).", "Tres medidas en la prensa (30 minutos)."), t("Find three government measures in this week’s news and classify each one as a law, an executive order, or a regulation, saying who made it. <em>Check:</em> if the story says “the agency proposed” or “public comments,” it is a regulation.", "Busque tres medidas del gobierno en las noticias de esta semana y clasifique cada una como ley, orden ejecutiva o reglamento, diciendo quién la produjo. <em>Compruebe:</em> si la nota dice «la agencia propuso» o «comentarios del público», es un reglamento.")),
        (t("Your agencies (15 minutes).", "Sus agencias (15 minutos)."), t("Write five problems from your daily life (a recall on a car seat, a dangerous workplace, a passport, a student loan, a polluted lot) and name the federal department or agency that handles each one. <em>Check:</em> look for the key word in the agency’s name.", "Anote cinco problemas de su vida diaria (un asiento de auto retirado del mercado, un lugar de trabajo peligroso, un pasaporte, un préstamo estudiantil, un terreno contaminado) y nombre el departamento o la agencia federal que atiende cada uno. <em>Compruebe:</em> busque la palabra clave en el nombre de la agencia.")),
    ]
    Q = t
