        (t("Tell law, order, and regulation apart", "Distingue ley, orden y reglamento"), t("I sort any measure by who made it and say how hard it is to undo.", "Clasifico cualquier medida por quién la produjo y digo lo que cuesta deshacerla."), t("I recognize laws but mix up orders and regulations.", "Reconozco las leyes, pero confundo órdenes y reglamentos."), t("I call them all “laws” (<a href=\"#s2\">review section 2</a>).", "A todas las llamo «leyes» (<a href=\"#s2\">repase la sección 2</a>).")),
