# ---------------------------------------------------------------- la práctica
def casos_medidas():
    G = [t("Law (Congress + President)", "Ley (Congreso + presidente)"), t("Executive order (President alone)", "Orden ejecutiva (el presidente solo)"), t("Regulation (an agency)", "Reglamento (una agencia)")]
    PL = t("Did both chambers of Congress vote on it?", "¿La votaron las dos cámaras del Congreso?")
    PO = t("Did the President sign it alone, with no vote in Congress?", "¿La firmó el presidente solo, sin votación del Congreso?")
    PR = t("Did an agency write it, under authority from a law?", "¿La escribió una agencia, con autoridad de una ley?")
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Sort each real measure by who made it.", "Clasifique cada medida real por quién la produjo."), "grupos": G, "etiqueta": t("This measure is a…", "Esta medida es…"),
                "piezas": [{"t": a, "v": v, "pista": [PL, PO, PR][v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("The Civil Rights Act of 1964, passed by Congress and signed by President Johnson", "La Ley de Derechos Civiles de 1964, aprobada por el Congreso y firmada por el presidente Johnson"), 0),
                                      (t("Executive Order 9066 (1942), signed by President Roosevelt, which led to the imprisonment of Japanese Americans", "La Orden Ejecutiva 9066 (1942), firmada por el presidente Roosevelt, que llevó al internamiento de los japoneses estadounidenses"), 1),
                                      (t("An OSHA rule on safety guards for machines, issued after public comments", "Una norma de la OSHA sobre protecciones de las máquinas, dictada tras comentarios públicos"), 2),
                                      (t("The Social Security Act of 1935", "La Ley del Seguro Social de 1935"), 0)]),
        caso(t("Set 2", "Serie 2"), [(t("Executive Order 8802 (1941), banning discrimination in defense industries", "La Orden Ejecutiva 8802 (1941), que prohibió la discriminación en las industrias de defensa"), 1),
                                      (t("The EPA’s limits on soot from power plants, written under the Clean Air Act", "Los límites de la EPA al hollín de las centrales eléctricas, escritos con base en la Ley de Aire Limpio"), 2),
                                      (t("The Americans with Disabilities Act of 1990", "La Ley de Estadounidenses con Discapacidades de 1990"), 0),
                                      (t("Executive Order 9981 (1948), ordering equal treatment in the armed forces", "La Orden Ejecutiva 9981 (1948), que ordenó la igualdad de trato en las fuerzas armadas"), 1)]),
        caso(t("Set 3", "Serie 3"), [(t("The FDA’s rule on the Nutrition Facts label on food packages", "La norma de la FDA sobre la etiqueta de información nutricional de los alimentos"), 2),
                                      (t("The Civil Liberties Act of 1988, which apologized for the internment", "La Ley de Libertades Civiles de 1988, que pidió perdón por el internamiento"), 0),
                                      (t("A Department of Transportation rule on how many hours truck drivers may drive", "Una norma del Departamento de Transporte sobre cuántas horas pueden conducir los camioneros"), 2),
                                      (t("A President’s order directing all federal agencies to buy American-made products when possible", "Una orden de un presidente que manda a todas las agencias federales comprar productos fabricados en el país cuando sea posible"), 1)]),
    ]


def banco_limites():
    datos = [
        (t("The President vetoes a bill.", "El presidente veta un proyecto."), [t("Congress can override with two-thirds of each chamber", "El Congreso puede anularlo con dos tercios de cada cámara"), t("The Supreme Court can sign the bill instead", "El Tribunal Supremo puede firmar el proyecto en su lugar"), t("The states can vote to pass it", "Los estados pueden votar para aprobarlo")]),
        (t("The President names a new Supreme Court justice.", "El presidente nombra a un nuevo juez del Tribunal Supremo."), [t("The Senate must confirm the nominee", "El Senado debe confirmar al candidato"), t("The House must elect the nominee", "La Cámara debe elegir al candidato"), t("The other justices must approve", "Los demás jueces deben aprobarlo")]),
        (t("The President signs a treaty with Canada.", "El presidente firma un tratado con Canadá."), [t("Two-thirds of the Senate must approve it", "Dos tercios del Senado deben aprobarlo"), t("A majority of the House must approve it", "La mayoría de la Cámara debe aprobarlo"), t("Nothing else is needed", "No hace falta nada más")]),
        (t("The President sends troops into a long war.", "El presidente envía tropas a una guerra larga."), [t("Congress declares war and decides whether to pay for it", "El Congreso declara la guerra y decide si la paga"), t("The Secretary of State must approve", "El secretario de Estado debe aprobarlo"), t("The Supreme Court must declare war", "El Tribunal Supremo debe declarar la guerra")]),
        (t("The President signs an executive order that goes beyond any law.", "El presidente firma una orden ejecutiva que va más allá de cualquier ley."), [t("Courts can strike it down", "Los tribunales pueden anularla"), t("Nothing: orders are final", "Nada: las órdenes son definitivas"), t("The states can rewrite it", "Los estados pueden reescribirla")]),
        (t("The President pardons a person convicted in an Illinois state court.", "El presidente indulta a una persona condenada en un tribunal del estado de Illinois."), [t("The pardon does not apply: only the governor can pardon state crimes", "El indulto no se aplica: solo el gobernador puede indultar delitos estatales"), t("The pardon is valid everywhere", "El indulto vale en todas partes"), t("The Senate must confirm the pardon", "El Senado debe confirmar el indulto")]),
    ]
    return [{"enun": "<strong>" + s + "</strong><br>" + t("What limits this power?", "¿Qué limita esta facultad?"), "ops": ops, "ok": 0, "exp": t("Checks and balances: another branch, or another level, has a say.", "Controles y equilibrios: otro poder, u otro nivel, tiene algo que decir.")} for s, ops in datos]


def banco_agencias():
    datos = [
        (t("A baby formula is making children sick.", "Una leche de fórmula está enfermando a los niños."), [t("Health and Human Services (FDA)", "Salud y Servicios Humanos (FDA)"), t("Defense", "Defensa"), t("Interior", "Interior"), t("Energy", "Energía")]),
        (t("A worker is hurt by an unsafe machine at a factory.", "Un trabajador se lesiona con una máquina insegura en una fábrica."), [t("Labor (OSHA)", "Trabajo (OSHA)"), t("Commerce", "Comercio"), t("State", "Estado"), t("Treasury", "Tesoro")]),
        (t("A town wants federal money to repair a bridge.", "Un pueblo quiere dinero federal para reparar un puente."), [t("Transportation", "Transporte"), t("Housing and Urban Development", "Vivienda y Desarrollo Urbano"), t("Agriculture", "Agricultura"), t("Justice", "Justicia")]),
        (t("A U.S. citizen needs a passport to travel abroad.", "Un ciudadano estadounidense necesita un pasaporte para viajar al extranjero."), [t("State", "Estado"), t("Homeland Security", "Seguridad Nacional"), t("Commerce", "Comercio"), t("Interior", "Interior")]),
        (t("A former soldier needs medical care.", "Un antiguo soldado necesita atención médica."), [t("Veterans Affairs", "Asuntos de los Veteranos"), t("Defense", "Defensa"), t("Labor", "Trabajo"), t("Education", "Educación")]),
        (t("A farmer wants help after a drought destroyed the crop.", "Un agricultor quiere ayuda después de que una sequía destruyera la cosecha."), [t("Agriculture", "Agricultura"), t("Interior", "Interior"), t("Energy", "Energía"), t("Commerce", "Comercio")]),
        (t("A family needs help paying rent in public housing.", "Una familia necesita ayuda para pagar el alquiler en una vivienda pública."), [t("Housing and Urban Development", "Vivienda y Desarrollo Urbano"), t("Treasury", "Tesoro"), t("Labor", "Trabajo"), t("Justice", "Justicia")]),
        (t("A factory is releasing smoke that breaks clean-air limits.", "Una fábrica emite humo que supera los límites de aire limpio."), [t("EPA (Environmental Protection Agency)", "EPA (Agencia de Protección Ambiental)"), t("Energy", "Energía"), t("Transportation", "Transporte"), t("Commerce", "Comercio")]),
        (t("The government needs to print paper money and collect federal taxes.", "El gobierno necesita imprimir billetes y cobrar los impuestos federales."), [t("Treasury", "Tesoro"), t("Commerce", "Comercio"), t("State", "Estado"), t("Labor", "Trabajo")]),
    ]
    return [{"enun": "<strong>" + s + "</strong><br>" + t("Which department or agency handles it?", "¿Qué departamento o agencia se ocupa?"), "ops": ops, "ok": 0, "exp": "<strong>" + ops[0] + ".</strong>"} for s, ops in datos]


def practica():
    A = {"en": ["law-order-rule", "powers", "agencies"], "es": ["ley-orden-reglamento", "facultades", "agencias"]}[C.L]
    mods = [
        (A[0], t("Law, order, or regulation?", "¿Ley, orden o reglamento?"), C.clasifica("m1", t("Ask: who made it? Both chambers and a signature (law), the President alone (order), or an agency under a law (regulation). If something is not right, the measures marked in yellow get a hint.", "Pregúntese: ¿quién la produjo? Las dos cámaras y una firma (ley), el presidente solo (orden) o una agencia con base en una ley (reglamento). Si algo no está bien, las medidas marcadas en amarillo reciben una pista."))),
        (A[1], t("Powers and limits", "Facultades y límites"), C.om("m2", t("For each presidential action, choose what limits it.", "Para cada acción presidencial, elija qué la limita."))),
        (A[2], t("Which agency?", "¿Qué agencia?"), C.om("m3", t("Look for the key word of the problem in the agency’s name.", "Busque la palabra clave del problema en el nombre de la agencia."))),
    ]
    js = C.js_datos("MED", casos_medidas()) + C.js_datos("LIM", banco_limites()) + C.js_datos("AGE", banco_agencias()) + 'creaClasifica("m1", MED);\ncreaBanco("m2", LIM);\ncreaBanco("m3", AGE);\n'
    return C.pagina_practica(N, titulo(), t("Three activities · the order of the exercises changes every time · two tries in each one", "Tres actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
